import * as path from 'node:path';
import * as fs from 'node:fs';
import { Storage } from '../config/storage.js';
import { CoreEvent, coreEvents } from './events.js';

/**
 * Filename of the sentinel file written once the user has acknowledged the
 * browser automation privacy notice. Its presence in the global Gemini
 * directory means consent has already been granted and should not be
 * requested again.
 */
const BROWSER_CONSENT_FILENAME = 'browser-consent-acknowledged.txt';

/**
 * Content written to the sentinel file when consent is acknowledged.
 */
const BROWSER_CONSENT_CONTENT = 'consent acknowledged';

/**
 * The privacy notice shown to the user before the browser agent starts.
 */
const BROWSER_CONSENT_PROMPT =
  'Privacy Notice\n\n' +
  'The browser automation feature launches a Chrome browser controlled by ' +
  'the CLI. Pages you visit and their contents may be sent to the model to ' +
  'fulfill your requests, and usage statistics may be collected to improve ' +
  'the product.\n\n' +
  'By continuing you acknowledge that your use is subject to the Google ' +
  'Privacy Policy: https://policies.google.com/privacy\n\n' +
  'Do you want to continue?';

/**
 * Resolves the absolute path to the browser consent sentinel file.
 */
function getBrowserConsentFilePath(): string {
  return path.join(Storage.getGlobalGeminiDir(), BROWSER_CONSENT_FILENAME);
}

/**
 * Writes the sentinel file recording that browser automation consent has been
 * acknowledged.
 */
function writeBrowserConsentFile(): void {
  const consentPath = getBrowserConsentFilePath();
  fs.mkdirSync(path.dirname(consentPath), { recursive: true });
  fs.writeFileSync(consentPath, BROWSER_CONSENT_CONTENT);
}

/**
 * Ensures the user has consented to browser automation data collection before
 * the browser agent starts.
 *
 * - If consent has already been acknowledged (the sentinel file exists),
 *   returns `true` immediately.
 * - In non-interactive mode (no listeners on `coreEvents`), consent is
 *   automatically accepted: the sentinel file is written and `true` is
 *   returned without emitting a consent request.
 * - In interactive mode (listeners on `coreEvents`), a consent request is
 *   emitted with a privacy notice. If the user accepts, the sentinel file is
 *   written and `true` is returned; if the user declines, no file is written
 *   and `false` is returned.
 */
export async function getBrowserConsentIfNeeded(): Promise<boolean> {
  if (fs.existsSync(getBrowserConsentFilePath())) {
    return true;
  }

  // Non-interactive mode: no UI listener to prompt, so auto-accept.
  if (coreEvents.listenerCount(CoreEvent.ConsentRequest) === 0) {
    writeBrowserConsentFile();
    return true;
  }

  // Interactive mode: ask the user via the UI.
  return new Promise<boolean>((resolve) => {
    coreEvents.emitConsentRequest({
      prompt: BROWSER_CONSENT_PROMPT,
      onConfirm: (confirmed: boolean) => {
        if (confirmed) {
          writeBrowserConsentFile();
          resolve(true);
        } else {
          resolve(false);
        }
      },
    });
  });
}
